#!/usr/bin/env node
/**
 * National Library of Norway (Nasjonalbiblioteket) digitised-map harvest.
 *
 * Discovery is the library's documented Catalog Search API:
 *   GET https://api.nb.no/catalog/v1/items?q=*&filter=contentClasses:digikart&size=100&page=N
 * The `digikart` content class is the library's own digitised-map class; the
 * response is HAL JSON with paging, per-item access/licence fields, a IIIF
 * Presentation link and a directly usable thumbnail/image-resolver link.
 *
 * Rights gate: an item is admitted only when its own API record says
 *   accessInfo.isPublicDomain === true
 *   accessInfo.license === "publicdomain"
 *   accessInfo.viewability === "ALL"
 *   accessInfo.accessAllowedFrom === "EVERYWHERE"
 * and its own content classes also include "publicdomain". A restrictive or
 * contradictory class/licence is withheld; nothing is relabelled. The library's
 * licence page defines Public Domain as all copyright and related rights having
 * lapsed and explicitly permits copying, modification, distribution, display
 * and performance, including commercially:
 *   https://www.nb.no/lisens/ (redirects to https://www.nb.no/tilgang/lisens/)
 * The page also warns that rights can differ outside Norway. That caveat is
 * retained on every record; no separate metadata licence is asserted.
 *
 * Usage:
 *   node scripts/harvest-nb.mjs                 # cached harvest, writes public/data
 *   node scripts/harvest-nb.mjs --refresh       # refetch all API pages
 *   node scripts/harvest-nb.mjs --no-write      # report only
 *   node scripts/harvest-nb.mjs --verify 20     # verification sample size
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readCore, shardPath, shardUrl, writeShard } from './catalogue.mjs';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const value = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/nb');
const REFRESH = has('refresh');
const WRITE = !has('no-write') && !has('dry-run');
const VERIFY_SAMPLE = Math.max(0, Number(value('verify', '15')) || 0);
const UA = 'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; National Library of Norway map harvest)';
const API = 'https://api.nb.no/catalog/v1/items';
const RETRIEVED = '2026-10-20';
const SHARD = shardUrl('nb');
const POLICY = 'https://www.nb.no/lisens/';
const LICENSE = 'https://www.nb.no/lisens/#public-domain';
const RECORD_BASE = 'https://www.nb.no/items/';
const INSTITUTION = 'National Library of Norway (Nasjonalbiblioteket)';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function pageUrl(page) {
  return `${API}?q=*&filter=contentClasses:digikart&size=100&page=${page}`;
}

async function fetchJson(url, tries = 4) {
  let last;
  for (let attempt = 0; attempt < tries; attempt += 1) {
    try {
      const res = await fetch(url, {
        headers: { accept: 'application/json', 'user-agent': UA },
        signal: AbortSignal.timeout(45_000),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return await res.json();
    } catch (error) {
      last = error;
      if (attempt + 1 < tries) await sleep(2_000 + attempt * 3_000);
    }
  }
  throw last;
}

/** Read one API page from the local cache, or fetch and cache it. */
async function getPage(page) {
  const file = resolve(CACHE, `page-${page}.json`);
  if (!REFRESH) {
    try {
      const doc = JSON.parse(await readFile(file, 'utf8'));
      if (Array.isArray(doc?._embedded?.items) && doc?.page?.totalElements != null) return doc;
    } catch {
      // cache miss or malformed cache: fetch below
    }
  }
  const doc = await fetchJson(pageUrl(page));
  if (!Array.isArray(doc?._embedded?.items)) throw new Error(`page ${page}: no _embedded.items array`);
  if (typeof doc?.page?.totalElements !== 'number' || typeof doc?.page?.totalPages !== 'number') {
    throw new Error(`page ${page}: missing page totals`);
  }
  await mkdir(CACHE, { recursive: true });
  await writeFile(file, `${JSON.stringify(doc)}\n`);
  return doc;
}

/** Traverse every page and return a de-duplicated item list in API order. */
export async function readItems() {
  const first = await getPage(0);
  const totalPages = first.page.totalPages;
  const totalElements = first.page.totalElements;
  const pages = [first];
  for (let page = 1; page < totalPages; page += 1) {
    pages.push(await getPage(page));
    await sleep(700);
  }
  const byId = new Map();
  let duplicates = 0;
  for (const doc of pages) {
    for (const item of doc._embedded.items) {
      if (!item || typeof item.id !== 'string') continue;
      if (byId.has(item.id)) {
        duplicates += 1;
        continue;
      }
      byId.set(item.id, item);
    }
  }
  return { items: [...byId.values()], pages: pages.length, totalElements, totalPages, duplicates };
}

/** The item's own affirmative public-domain evidence, or a withhold reason. */
export function rightsGate(item) {
  const access = item?.accessInfo ?? {};
  const classes = item?.metadata?.contentClasses ?? [];
  if (access.isDigital !== true) return { ok: false, reason: 'not a digital item' };
  if (access.isPublicDomain !== true) return { ok: false, reason: 'not marked public domain' };
  if (access.license !== 'publicdomain') return { ok: false, reason: `licence is ${access.license ?? 'unstated'}` };
  if (access.viewability !== 'ALL') return { ok: false, reason: `viewability is ${access.viewability ?? 'unstated'}` };
  if (access.accessAllowedFrom !== 'EVERYWHERE') return { ok: false, reason: `access is limited to ${access.accessAllowedFrom ?? 'unknown'}` };
  if (!classes.includes('publicdomain')) return { ok: false, reason: 'content classes do not confirm public domain' };
  for (const restricted of ['copyrighted', 'ccbync', 'ccbyncnd', 'bokhylla']) {
    if (classes.includes(restricted)) return { ok: false, reason: `conflicting content class ${restricted}` };
  }
  return { ok: true, basis: 'public-domain' };
}

/** All 4-digit years in a publication statement (no inference from other fields). */
export function publicationYears(text) {
  const years = [...String(text ?? '').matchAll(/\b(1[4-9]\d{2}|20\d{2})\b/g)].map((m) => Number(m[1]));
  if (!years.length) return null;
  return { start: Math.min(...years), end: Math.max(...years) };
}

const short = (value) => (typeof value === 'string' && value.trim() ? value.trim() : null);

/** Build one catalogue record from one API item. Returns { record, reason }. */
export function recordFrom(item, { retrieved = RETRIEVED } = {}) {
  const gate = rightsGate(item);
  if (!gate.ok) return { record: null, reason: gate.reason };
  const meta = item.metadata ?? {};
  const title = short(meta.title) ?? short(meta.titleInfos?.[0]?.title);
  if (!title) return { record: null, reason: 'no catalogue title' };

  const links = item._links ?? {};
  const recordUrl = `${RECORD_BASE}${item.id}`;
  const manifest = short(links.presentation?.href);
  const thumbnail = short(links.thumbnail_large?.href);
  const custom = short(links.thumbnail_custom?.href);
  const imageService = custom ? custom.split('/full/')[0] : null;
  const identifiers = meta.identifiers ?? {};
  const issued = short(meta.originInfo?.issued);
  const years = publicationYears(issued);
  const geo = meta.geographic ?? {};
  const places = [...new Set(Object.values(geo).filter((value) => typeof value === 'string' && value.trim()).map((value) => value.trim()))];
  const subjectGeo = meta.subject?.geographics ?? [];
  const subjects = [...new Set([...subjectGeo, ...(meta.subject?.topics ?? [])].filter((value) => typeof value === 'string' && value.trim()))];
  const languages = (meta.languages ?? []).map((entry) => entry?.code).filter((code) => typeof code === 'string' && code.trim());
  const creators = (meta.creators ?? []).filter((creator) => typeof creator === 'string' && creator.trim());
  const pageCount = Number.isInteger(meta.pageCount) && meta.pageCount > 0 ? meta.pageCount : null;

  const record = {
    id: `nb:${item.id}`,
    title,
    creators,
    providerId: 'nb',
    institution: INSTITUTION,
    collection: 'Digitised maps — National Library of Norway',
    originalCollection: 'digikart',
    rights:
      'Public Domain (Nasjonalbiblioteket item licence “publicdomain”; all copyright and related rights have lapsed in Norway). The National Library warns that rights can differ in other jurisdictions. Credit: Nasjonalbiblioteket.',
    rightsBasis: gate.basis,
    rightsUrl: LICENSE,
    rightsPolicyUrl: POLICY,
    rightsNote:
      'The item’s Catalog Search record states accessInfo.isPublicDomain=true and accessInfo.license=publicdomain; its content classes include digikart and publicdomain. Nasjonalbiblioteket’s licence page defines Public Domain as all copyright and related rights having lapsed and permits copying, modification, distribution, display and performance, including commercially. The page notes that rights may differ outside Norway. No separate metadata licence is asserted.',
    attribution: `Nasjonalbiblioteket (National Library of Norway), ${recordUrl} (Public Domain)`,
    recordUrl,
    viewerUrl: recordUrl,
    metadataSource: `https://api.nb.no/catalog/v1/items/${item.id}`,
    type: 'map',
    retrieved,
    geoNote:
      'Nasjonalbiblioteket does not state a map extent, projection or alignment for this digitised item; no place anchor, boundary or pixel transform is inferred. The IIIF image service is the original delivered scan.',
  };
  if (manifest) record.iiifManifest = manifest;
  if (thumbnail) record.thumbnail = thumbnail;
  if (imageService) record.imageService = imageService;
  if (identifiers.urn) record.urn = identifiers.urn;
  if (identifiers.oaiId) record.oaiId = identifiers.oaiId;
  if (pageCount) {
    record.pageCount = pageCount;
    record.imageCount = pageCount;
  }
  if (issued) {
    record.dateDisplay = issued;
    if (years) {
      record.yearStart = years.start;
      record.yearEnd = years.end;
    }
  } else {
    record.dateNote = 'Nasjonalbiblioteket states no publication date for this item; no date is inferred.';
  }
  if (languages.length) record.languages = languages;
  if (places.length) {
    record.place = places[0];
    record.subjectPlaces = places;
  }
  if (subjects.length) record.subjects = subjects;
  const publisher = short(meta.originInfo?.publisher);
  if (publisher) record.publisher = publisher;
  return { record, reason: null };
}

async function verify(records) {
  if (!VERIFY_SAMPLE || !records.length) return { sample: 0 };
  const step = Math.max(1, Math.floor(records.length / VERIFY_SAMPLE));
  const sample = [];
  for (let i = 0; i < records.length && sample.length < VERIFY_SAMPLE; i += step) sample.push(records[i]);
  const results = [];
  for (const record of sample) {
    const one = { id: record.id };
    const check = async (key, url, type) => {
      try {
        const res = await fetch(url, {
          headers: { accept: type === 'json' ? 'application/json' : 'image/*', range: 'bytes=0-2047', 'user-agent': UA },
          signal: AbortSignal.timeout(20_000),
        });
        const body = await res.arrayBuffer();
        one[key] = { status: res.status, type: res.headers.get('content-type'), bytes: body.byteLength };
        return { ok: (res.status === 200 || res.status === 206) && (!type || String(res.headers.get('content-type') ?? '').startsWith(type)), body, res };
      } catch (error) {
        one[key] = { status: 0, error: String(error.message) };
        return { ok: false };
      }
    };
    const thumb = await check('thumbnail', record.thumbnail, 'image/');
    await sleep(300);
    const info = await check('info', `${record.imageService}/info.json`, 'application/json');
    await sleep(300);
    const manifest = await check('manifest', record.iiifManifest, 'application/json');
    let manifestLicense = null;
    if (manifest.ok) {
      try {
        manifestLicense = JSON.parse(new TextDecoder().decode(manifest.body))?.license ?? null;
      } catch {
        manifestLicense = null;
      }
    }
    await sleep(300);
    const page = await check('record', record.recordUrl, 'text/html');
    one.manifestLicense = manifestLicense;
    one.thumbnailOk = thumb.ok;
    one.infoOk = info.ok;
    one.manifestOk = manifest.ok;
    one.recordOk = page.ok;
    results.push(one);
    await sleep(500);
  }
  return {
    retrieved: RETRIEVED,
    sample: results.length,
    thumbnailOk: results.filter((r) => r.thumbnailOk).length,
    infoOk: results.filter((r) => r.infoOk).length,
    manifestOk: results.filter((r) => r.manifestOk).length,
    manifestLicenseOk: results.filter((r) => /public-domain|publicdomain/i.test(r.manifestLicense ?? '')).length,
    recordOk: results.filter((r) => r.recordOk).length,
    examples: results.slice(0, 8),
    note:
      'Thumbnail, IIIF Image API info.json, IIIF manifest and record page were requested directly from the library. A failed request is recorded, not converted into a successful import; the catalogue record still comes from the item JSON.',
  };
}

async function main() {
  const { items, pages, totalElements, totalPages, duplicates } = await readItems();
  console.log(`National Library of Norway digikart: ${totalElements} reported, ${items.length} unique items in ${pages}/${totalPages} pages (${duplicates} duplicates)`);
  const records = [];
  const withheld = {};
  const basis = {};
  for (const item of items) {
    const { record, reason } = recordFrom(item);
    if (!record) {
      const key = reason ?? 'unknown';
      withheld[key] = (withheld[key] || 0) + 1;
      continue;
    }
    records.push(record);
    basis[record.rightsBasis] = (basis[record.rightsBasis] || 0) + 1;
  }
  if (!records.length) throw new Error('No eligible National Library of Norway records; leaving the catalogue unchanged.');
  records.sort(
    (a, b) => (a.yearStart ?? Number.POSITIVE_INFINITY) - (b.yearStart ?? Number.POSITIVE_INFINITY) || a.id.localeCompare(b.id),
  );
  const dated = records.filter((record) => record.yearStart != null);
  console.log(`Eligible National Library of Norway records: ${records.length} of ${items.length}`);
  console.log('Rights bases:', basis);
  console.log('Withheld:', Object.fromEntries(Object.entries(withheld).sort((a, b) => b[1] - a[1])));
  console.log(
    'Dates:',
    dated.length,
    'undated:',
    records.length - dated.length,
    'range:',
    dated.length ? `${Math.min(...dated.map((record) => record.yearStart))}–${Math.max(...dated.map((record) => record.yearEnd))}` : 'none',
  );
  console.log('Multi-page works:', records.filter((record) => (record.pageCount ?? 0) > 1).length);
  const verification = await verify(records);
  console.log('Verification sample:', verification);
  const selection = {
    source: 'National Library of Norway — digitised maps (digikart)',
    endpoint: pageUrl(0),
    filter: 'contentClasses:digikart',
    reportedTotal: totalElements,
    pages,
    examined: items.length,
    kept: records.length,
    withheld: items.length - records.length,
    duplicatesAcrossPages: duplicates,
    shard: SHARD,
    rightsBasis: basis,
    withheldReasons: withheld,
    undated: records.length - dated.length,
    multiPageWorks: records.filter((record) => (record.pageCount ?? 0) > 1).length,
    rule:
      'The documented Catalog Search API is traversed for the library’s digikart content class. An item is admitted only when its own record is digital, isPublicDomain=true, license=publicdomain, viewability=ALL, accessAllowedFrom=EVERYWHERE, and its content classes include publicdomain; contradictory/restrictive classes, non-public-domain licences and limited-view items are withheld. Original titles, creators, dates, places, languages, page counts, URN/OAI identifiers, thumbnail, IIIF manifest and image service are transcribed; missing date/extent stays missing and no alignment is invented.',
    policy: {
      url: POLICY,
      statement:
        'Nasjonalbiblioteket’s licence page defines Public Domain as all copyright and related rights having lapsed, and permits copying, modification, distribution, display and performance, including commercially, without permission. It warns that rights can differ outside Norway. The per-item licence and public-domain flag are retained on every record; no separate metadata licence is asserted.',
    },
    verification,
    retrieved: RETRIEVED,
  };
  const generatedAt = new Date().toISOString();
  const method =
    'National Library of Norway Catalog Search API: documented digikart discovery, per-item Public Domain gate, IIIF manifest/image-service links and a resumable page cache.';
  const provider = {
    id: 'nb',
    name: 'National Library of Norway — digitised maps',
    operator: 'National Library of Norway (Nasjonalbiblioteket)',
    homepage: 'https://www.nb.no/',
    home: 'https://www.nb.no/',
    institutions: [INSTITUTION],
    rights:
      'Per-item Public Domain: the item record and IIIF manifest carry isPublicDomain=true and license=publicdomain, and the library’s licence page permits copying, distribution, display and performance, including commercially. The library warns that rights can differ outside Norway. Records without the affirmative per-item public-domain evidence are withheld; restrictive classes and licences are never relabelled.',
    attribution: 'Nasjonalbiblioteket (National Library of Norway)',
    terms: POLICY,
    retrieved: RETRIEVED,
    api: {
      discovery: pageUrl(0).replace('page=0', 'page={page}'),
      item: 'https://api.nb.no/catalog/v1/items/{id}',
      manifest: 'https://api.nb.no/catalog/v1/iiif/{id}/manifest',
      image: 'https://www.nb.no/services/image/resolver/{imageId}',
      documentation: 'https://api.nb.no/',
    },
    apiHosts: ['api.nb.no', 'www.nb.no'],
    method,
    metadataReuse: {
      status: 'basis-recorded',
      decided: generatedAt,
      basis:
        'Every admitted item’s own API record carries accessInfo.isPublicDomain=true, accessInfo.license=publicdomain and the publicdomain content class; its IIIF manifest carries license https://www.nb.no/lisens/#public-domain. Nasjonalbiblioteket’s licence page defines Public Domain as all copyright and related rights having lapsed and permits copying, modification, distribution, display and performance, including commercially. The redistributed fields are the factual description the library publishes for that public-domain object. No separate metadata licence is asserted.',
      primaryEvidence: [
        {
          url: 'https://www.nb.no/lisens/',
          retrieved: RETRIEVED,
          quote:
            'Objektene i Nettbiblioteket er alle merket med en angivelse av om, og eventuelt hvordan, du kan gjenbruke materialet.',
        },
        {
          url: 'https://www.nb.no/lisens/',
          retrieved: RETRIEVED,
          quote:
            'Dette verket har blitt identifisert som «falt i det fri», det vil si at alle opphavsrettigheter til verket er falt bort, inklusive alle nærstående rettigheter. Du kan kopiere, endre, spre, vise og fremføre verket, også for kommersielle formål, uten å spørre om tillatelse.',
        },
        {
          url: 'https://www.nb.no/lisens/',
          retrieved: RETRIEVED,
          quote:
            'Det er ikke sikkert at alle opphavsrettigheter til verket er falt bort i andre jurisdiksjoner enn Norge.',
        },
      ],
      limits:
        'Only items whose own record and classes affirm public domain are admitted. CC BY-NC, CC BY-NC-ND, copyrighted, limited-view and other non-public-domain items stay withheld. The Norwegian Public Domain determination is not stretched to other jurisdictions; the library’s caveat is retained on every record.',
      decisionNote: 'coordination/sources-20261020-0.md',
    },
    collections: [
      {
        id: 'digikart',
        name: 'Digitised maps (digikart)',
        discovery: pageUrl(0).replace('page=0', 'page={page}'),
      },
    ],
    verification,
  };
  const corePath = resolve(OUT, 'records.json');
  const sourcesPath = resolve(OUT, 'sources.json');
  const core = await readCore(OUT);
  const sources = JSON.parse(await readFile(sourcesPath, 'utf8'));
  core.shards = [...new Set([...(core.shards ?? []), SHARD])].sort();
  core.records = (core.records ?? []).filter((record) => record.providerId !== 'nb');
  core.generatedAt = generatedAt;
  core.retrieved = RETRIEVED;
  const priorMethod = String(core.method ?? '').split(method).join(' ').replace(/\s+/g, ' ').trim();
  core.method = priorMethod ? `${priorMethod} ${method}` : method;
  core.selection ??= {};
  core.selection['nb:digikart'] = selection;
  sources.providers = [...sources.providers.filter((source) => source.id !== 'nb'), provider].sort((a, b) => a.id.localeCompare(b.id));
  sources.generatedAt = generatedAt;
  const shardDoc = { generatedAt, retrieved: RETRIEVED, providerId: 'nb', method, selection, records };
  const coreBytes = Buffer.byteLength(JSON.stringify(core, null, 2));
  const shardBytes = Buffer.byteLength(JSON.stringify(shardDoc));
  console.log(
    `Catalogue would be ${core.records.length} core + ${records.length} National Library of Norway records; core ${(coreBytes / 1024 / 1024).toFixed(2)} MiB, shard ${(shardBytes / 1024 / 1024).toFixed(2)} MiB`,
  );
  if (coreBytes > 24 * 1024 * 1024 || shardBytes > 24 * 1024 * 1024) throw new Error('A catalogue asset exceeds 24 MiB; split it before writing.');
  if (WRITE) {
    await mkdir(dirname(shardPath(OUT, SHARD)), { recursive: true });
    await writeShard(OUT, SHARD, records, { retrieved: RETRIEVED, providerId: 'nb', method, selection });
    await writeFile(corePath, `${JSON.stringify(core, null, 2)}\n`);
    await writeFile(sourcesPath, `${JSON.stringify(sources, null, 2)}\n`);
    console.log('Wrote', corePath, 'and', shardPath(OUT, SHARD));
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}
